import{_ as a,o as d,c as e,a2 as i}from"./chunks/framework.XctAhZuT.js";const p=JSON.parse('{"title":"AI 工作流","description":"所有 LLM 请求经过统一 AI 引擎。领域模块构造 Prompt、解析结果并执行本地校验。AI 输出不是直接可执行状态。","frontmatter":{"description":"所有 LLM 请求经过统一 AI 引擎。领域模块构造 Prompt、解析结果并执行本地校验。AI 输出不是直接可执行状态。"},"headers":[],"relativePath":"guide/ai-workflows.md","filePath":"guide/ai-workflows.md","lastUpdated":1787830168000}'),r={name:"guide/ai-workflows.md"};function o(l,t,h,n,s,c){return d(),e("div",null,[...t[0]||(t[0]=[i('<h1 id="ai-工作流" tabindex="-1">AI 工作流 <a class="header-anchor" href="#ai-工作流" aria-label="Permalink to &quot;AI 工作流&quot;">​</a></h1><p>所有 LLM 请求经过统一 AI 引擎。领域模块构造 Prompt、解析结果并执行本地校验。AI 输出不是直接可执行状态。</p><h2 id="功能矩阵" tabindex="-1">功能矩阵 <a class="header-anchor" href="#功能矩阵" aria-label="Permalink to &quot;功能矩阵&quot;">​</a></h2><table tabindex="0"><thead><tr><th>工作流</th><th>输入</th><th>输出</th><th>写入边界</th></tr></thead><tbody><tr><td>提示助手</td><td>当前题目与允许的课程上下文</td><td>分层提示</td><td>会话与学习证据</td></tr><tr><td>深度讲解</td><td>句子、语法点或错误</td><td>结构化解释</td><td>可选知识笔记</td></tr><tr><td>SRS 导师</td><td>错题、弱词、近期复习</td><td>临时复习课</td><td>校验后进入课程流程</td></tr><tr><td>许愿生成</td><td>多轮需求、附件</td><td>Section JSON 草稿</td><td>人工确认后写入</td></tr><tr><td>教材导入</td><td>文本章节与预设</td><td>资源和课时草稿</td><td>审校、合并后写入</td></tr><tr><td>课程生成</td><td>AI Hub 入口，普通/许愿模式</td><td>Section JSON 草稿</td><td><code>ai_fixer</code> 自动修复后，经校验与确认写入</td></tr><tr><td>Lesson 助手</td><td>当前 Lesson</td><td>修改建议或内容</td><td>经 schema 校验后应用</td></tr></tbody></table><h2 id="提示深度" tabindex="-1">提示深度 <a class="header-anchor" href="#提示深度" aria-label="Permalink to &quot;提示深度&quot;">​</a></h2><p>提示不是由逐级解锁的状态机控制的。实际机制是 <code>AiExplainPrefsSnapshot</code> 的一组平铺偏好——回复语言、讲解深度、是否允许直接揭晓答案、是否注入学习者上下文——再由 <code>toSystemPromptRules()</code> 拼成规则文本进入系统提示，由模型在该约束内作答。</p><p>换句话说，深度取决于用户选择的偏好档位，而不是「每次追问才解锁下一层」的固定阶段序列。</p><h2 id="学习者上下文" tabindex="-1">学习者上下文 <a class="header-anchor" href="#学习者上下文" aria-label="Permalink to &quot;学习者上下文&quot;">​</a></h2><p><code>LearnerAiContext</code>（<code>lib/application/ai/learner_ai_context.dart</code>）从本地证据生成只读摘要。关闭注入学习者上下文后：</p><ul><li>不发送学习者摘要。</li><li>不发送错题与弱词历史。</li><li>当前用户主动输入仍按本次请求发送。</li></ul><h2 id="结构化输出" tabindex="-1">结构化输出 <a class="header-anchor" href="#结构化输出" aria-label="Permalink to &quot;结构化输出&quot;">​</a></h2><p>AI 生成课程或题目时执行以下门禁：</p><ol><li>解析 JSON。</li><li>应用 schema。</li><li>修复允许自动修复的 ID 冲突或引用断裂。</li><li>运行课程 validator。</li><li>显示 diff 或预览。</li><li>等待用户确认。</li><li>写入 JSON 真理源。</li></ol><p>无法解析的输出不做部分写入。</p><h2 id="会话数据" tabindex="-1">会话数据 <a class="header-anchor" href="#会话数据" aria-label="Permalink to &quot;会话数据&quot;">​</a></h2><p>原生平台可保存会话、消息与诊断。 tutor 会话支持列出、切换、新建与删除；当前没有重命名与导出功能。未配置模型时 AI 面板显示未配置引导，不做本地片段的确定性讲解。</p><h2 id="明确不提供" tabindex="-1">明确不提供 <a class="header-anchor" href="#明确不提供" aria-label="Permalink to &quot;明确不提供&quot;">​</a></h2><ul><li>未经可靠模型验证的口音分数或音素分数。</li><li>在用户不知情时上传完整学习数据库。</li><li>让远端模型直接写 SQLite。</li><li>绕过课程校验器的自动发布。</li></ul><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/ai-configuration">配置 AI</a></li><li><a href="/docs/guide/mistakes-and-weak-items">错题与弱项</a></li><li><a href="/docs/authoring/textbook-import">教材导入</a></li></ul>',20)])])}const f=a(r,[["render",o]]);export{p as __pageData,f as default};
